// src/pages/DashboardProf.jsx
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

const DashboardProf = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchUserData = async () => {
      const userData = localStorage.getItem("user");
      if (!userData) {
        navigate("/login");
        return;
      }

      const userObj = JSON.parse(userData);
      if (userObj.role !== "teacher") {
        alert("❌ Accès réservé aux professeurs");
        navigate("/login");
        return;
      }

      setUser(userObj);
      await fetchTeacherStats(userObj.id);
    };

    fetchUserData();
  }, [navigate]);

  // Fonction pour récupérer les statistiques du professeur depuis l'API
  const fetchTeacherStats = async (teacherId) => {
    try {
      setLoading(true);
      const token = localStorage.getItem("token");
      
      // Simulation d'appel API - À remplacer par votre véritable endpoint
      const response = await fetch(`/api/teachers/${teacherId}/stats`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      if (response.ok) {
        const data = await response.json();
        setStats(data);
      } else {
        console.error("Erreur lors de la récupération des statistiques");
        // Valeurs par défaut en cas d'erreur
        setStats({
          coursesCount: 0,
          studentsCount: 0,
          pendingAssignments: 0,
          successRate: 0
        });
      }
    } catch (error) {
      console.error("Erreur:", error);
      setStats({
        coursesCount: 0,
        studentsCount: 0,
        pendingAssignments: 0,
        successRate: 0
      });
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("user");
    localStorage.removeItem("token");
    navigate("/login");
  };

  const handleMenuClick = (menuItem) => {
    // Navigation vers les différentes pages selon l'action
    switch(menuItem) {
      case "Voir mes cours":
        navigate("/mes-cours");
        break;
      case "Voir les étudiants":
        navigate("/etudiants");
        break;
      case "Gérer les notes":
        navigate("/notes");
        break;
      case "Voir les rapports":
        navigate("/rapports");
        break;
      default:
        break;
    }
  };

  const menuItems = [
    { label: "Voir mes cours", icon: "📚", color: "#3B82F6" },
    { label: "Voir les étudiants", icon: "👨‍🎓", color: "#10B981" },
    { label: "Gérer les notes", icon: "📊", color: "#F59E0B" },
    { label: "Voir les rapports", icon: "📋", color: "#8B5CF6" }
  ];

  if (!user) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Chargement du tableau de bord...</p>
      </div>
    );
  }

  return (
    <div className="dashboard-prof">
      {/* Header */}
      <header className="dashboard-header">
        <div className="header-content">
          <div className="header-info">
            <h1>Tableau de Bord Professeur</h1>
            <p>Gestion académique et pédagogique</p>
          </div>
          <div className="header-actions">
            <div className="user-info">
              <span className="user-name">Prof. {user.nom}</span>
              <span className="user-role">{user.role}</span>
            </div>
            <button className="logout-btn" onClick={handleLogout}>
              <span>🚪</span>
              Déconnexion
            </button>
          </div>
        </div>
      </header>

      {/* Welcome Section */}
      <section className="welcome-section">
        <div className="welcome-card">
          <div className="welcome-content">
            <div className="welcome-text">
              <h2>Bonjour, Professeur {user.nom} 👨‍🏫</h2>
              <p>Bienvenue sur votre espace de gestion pédagogique</p>
            </div>
            <div className="profile-avatar">
              <span>👨‍🏫</span>
            </div>
          </div>
          <div className="user-details">
            <div className="detail-item">
              <strong>📧 Email:</strong>
              <span>{user.email}</span>
            </div>
            <div className="detail-item">
              <strong>🎯 Rôle:</strong>
              <span className="role-badge">{user.role}</span>
            </div>
            <div className="detail-item">
              <strong>🆔 ID:</strong>
              <span>{user.id}</span>
            </div>
          </div>
        </div>
      </section>

      {/* Menu Grid */}
      <section className="menu-section">
        <h3 className="section-title">Actions Rapides</h3>
        <div className="menu-grid">
          {menuItems.map((item, index) => (
            <button
              key={index}
              className="menu-card"
              style={{ '--accent-color': item.color }}
              onClick={() => handleMenuClick(item.label)}
            >
              <div className="card-icon" style={{ backgroundColor: item.color }}>
                {item.icon}
              </div>
              <span className="card-label">{item.label}</span>
            </button>
          ))}
        </div>
      </section>

      {/* Stats Section */}
      <section className="stats-section">
        <h3 className="section-title">Aperçu du Semestre</h3>
        {loading ? (
          <div className="stats-loading">
            <div className="loading-spinner"></div>
            <p>Chargement des statistiques...</p>
          </div>
        ) : (
          <div className="stats-grid">
            <div className="stat-card">
              <div className="stat-icon">📚</div>
              <div className="stat-info">
                <h4>{stats?.coursesCount || 0}</h4>
                <p>Cours assignés</p>
              </div>
            </div>
            <div className="stat-card">
              <div className="stat-icon">👨‍🎓</div>
              <div className="stat-info">
                <h4>{stats?.studentsCount || 0}</h4>
                <p>Étudiants</p>
              </div>
            </div>
            <div className="stat-card">
              <div className="stat-icon">📝</div>
              <div className="stat-info">
                <h4>{stats?.pendingAssignments || 0}</h4>
                <p>Devoirs en attente</p>
              </div>
            </div>
            <div className="stat-card">
              <div className="stat-icon">✅</div>
              <div className="stat-info">
                <h4>{stats?.successRate || 0}%</h4>
                <p>Taux de réussite</p>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* Section Cours Récent */}
      <section className="recent-courses-section">
        <h3 className="section-title">Cours Récents</h3>
        <div className="courses-list">
          {/* Ici vous pouvez ajouter un appel API pour les cours récents */}
          <p className="no-data">Les cours récents seront affichés ici</p>
        </div>
      </section>
    </div>
  );
};

export default DashboardProf;
